create or replace function public.update_waiter_pending_item(target_item_id uuid,new_quantity integer) returns jsonb language plpgsql security definer set search_path=public as $$
declare item order_items; waiter restaurant_staff; new_invoice_total numeric; new_order_total numeric;
begin select * into item from order_items x where x.id=target_item_id for update;select * into waiter from restaurant_staff s where s.restaurant_id=item.restaurant_id and s.user_id=auth.uid() and s.active and s.role::text='waiter' limit 1;if item.id is null or waiter.id is null then raise exception 'Pending item not found.';end if;if item.kitchen_status not in('held','paid') then raise exception 'Kitchen already accepted this item.';end if;if new_quantity<0 or new_quantity>99 then raise exception 'Quantity must be between 0 and 99.';end if;if new_quantity=0 then delete from order_items where id=item.id;else update order_items set quantity=new_quantity where id=item.id;end if;select coalesce(sum(quantity*price),0) into new_invoice_total from order_items where invoice_id=item.invoice_id;update order_invoices set total_price=new_invoice_total,updated_at=now() where id=item.invoice_id;select coalesce(sum(quantity*price),0) into new_order_total from order_items where order_id=item.order_id;update orders set total_price=new_order_total,dining_session_last_activity_at=now(),updated_at=now() where id=item.order_id;return jsonb_build_object('order_id',item.order_id,'invoice_total',new_invoice_total,'order_total',new_order_total,'cancelled',new_quantity=0);end;$$;
revoke all on function public.update_waiter_pending_item(uuid,integer) from public,anon;
grant execute on function public.update_waiter_pending_item(uuid,integer) to authenticated,service_role;
